use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  pub api_alarm_settings: Isolette_Thermostat_Rust::AlarmTemperatureSettings,
  pub api_monitor_mode: Isolette_Thermostat_Rust::ThermostatMode
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_current_temperature(container.api_current_temperature);
  put_alarm_settings(container.api_alarm_settings);
  put_monitor_mode(container.api_monitor_mode);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  current_temperature: Isolette_Thermostat_Rust::CurrentTemperature,
  alarm_settings: Isolette_Thermostat_Rust::AlarmTemperatureSettings,
  monitor_mode: Isolette_Thermostat_Rust::ThermostatMode)
{
  put_current_temperature(current_temperature);
  put_alarm_settings(alarm_settings);
  put_monitor_mode(monitor_mode);
}

/// setter for IN DataPort
pub fn put_current_temperature(value: Isolette_Thermostat_Rust::CurrentTemperature)
{
  *extern_api::IN_current_temperature.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_alarm_settings(value: Isolette_Thermostat_Rust::AlarmTemperatureSettings)
{
  *extern_api::IN_alarm_settings.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_monitor_mode(value: Isolette_Thermostat_Rust::ThermostatMode)
{
  *extern_api::IN_monitor_mode.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_interface_facts() -> Isolette_Thermostat_Rust::MonitorInterfaceFacts
{
  return extern_api::OUT_interface_facts.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_monitor_status() -> Isolette_Thermostat_Rust::ThermostatStatusValue
{
  return extern_api::OUT_monitor_status.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_control_basis() -> Isolette_Thermostat_Rust::MonitorControlBasis
{
  return extern_api::OUT_control_basis.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
